def recut(rel,term,window):
 j=window.find(term);assert j>=0;a=max(0,j-55);b=min(len(window),j+len(term)+75);q=window[a:b]
 # ensure the evidence identity is a single headword token
 if q.count(term)>1:q=q[:q.find(term)+len(term)+35]
 v=zc.verify(rel,q)
 if not v.get('ok') or q.count(term)!=1:
  q=term;v=zc.verify(rel,q)
 assert v.get('ok') and q.count(term)==1
 return q,v
